 * Why the core did not do what it was asked.
 */
public 
enum CoreRefusal: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case KeyDoesNotFit
    case NotFound(what: String
    )
    case Invalid(detail: String
    )
    case Storage(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

